        "text": "postfix increment example",
        "refs": ["Q0000"]
      },
      "example_type": null,
      "example_text": {
        "text": "int X = 1; int Y = X++; // Y becomes 1, X becomes 2",
        "refs": ["Q0000"]
      }
    },
    {
      "exemplifies": {
        "text": "prefix increment example",
        "refs": ["Q0001"]
      },
      "example_type": null,
      "example_text": {
        "text": "int X = 1; int Y = ++X; // both X and Y become 2",
        "refs": ["Q0001"]
