    },
    {
      "exemplifies": {
        "text": "operator precedence example",
        "refs": ["Q0003"]
      },
      "example_type": null,
      "example_text": {
        "text": "int result = 10 + 3 * 2; // result is 16 because 3*2 evaluated first",
        "refs": ["Q0003"]
      }
    },
    {
      "exemplifies": {
        "text": "parentheses to change precedence example",
        "refs": ["Q0004"]
      },
      "example_type": null,
      "example_text": {
        "text": "int result = (10 + 3) * 2; // result is 26 because parentheses force addition first",
        "refs": ["Q0004"]
      }
    }
  ],
